@Override
                public int indexOfChild(final ImmutableNode parent, final ImmutableNode child) {
                    final List<ImmutableNode> children = super.getChildren(parent);
                    return filterChildrenOfGlobalSection(parent, children).indexOf(child);
                }

@Override
                protected NodeHandler<ImmutableNode> getDecoratedNodeHandler() {
                    return GlobalSectionNodeModel.super.getNodeHandler();
                }

private List<ImmutableNode> filterChildrenOfGlobalSection(final ImmutableNode node, final List<ImmutableNode> children) {
                    final List<ImmutableNode> filteredList;
                    if (node == getRootNode()) {
                        filteredList = new ArrayList<>(children.size());
                        for (final ImmutableNode child : children) {
                            if (!isSectionNode(child)) {
                                filteredList.add(child);
                            }
                        }
                    } else {
                        filteredList = children;
                    }

                    return filteredList;
                }

public Map<String, Object> getMap() {
        return map;
    }

public boolean isTrimmingDisabled() {
        return trimmingDisabled;
    }

public void setTrimmingDisabled(final boolean trimmingDisabled) {
        this.trimmingDisabled = trimmingDisabled;
    }

@Override
    protected Object getPropertyInternal(final String key) {
        final Object value = map.get(key);
        if (value instanceof String) {
            final Collection<String> list = getListDelimiterHandler().split((String) value, !isTrimmingDisabled());
            return list.size() > 1 ? list : list.iterator().next();
        }
        return value;
    }

@Override
    protected void addPropertyDirect(final String key, final Object value) {
        final Object previousValue = getProperty(key);

        if (previousValue == null) {
            map.put(key, value);
        } else if (previousValue instanceof List) {
            // the value is added to the existing list
            // Note: This is problematic. See header comment!
            ((List<Object>) previousValue).add(value);
        } else {
            // the previous value is replaced by a list containing the previous value and the new value
            final List<Object> list = new ArrayList<>();
            list.add(previousValue);
            list.add(value);

            map.put(key, list);
        }
    }

@Override
    protected boolean isEmptyInternal() {
        return map.isEmpty();
    }

@Override
    protected boolean containsKeyInternal(final String key) {
        return map.containsKey(key);
    }

@Override
    protected void clearPropertyDirect(final String key) {
        map.remove(key);
    }

@Override
    protected Iterator<String> getKeysInternal() {
        return map.keySet().iterator();
    }

@Override
    protected int sizeInternal() {
        return map.size();
    }

@Override
    public Object clone() {
        try {
            final MapConfiguration copy = (MapConfiguration) super.clone();
            // Safe because ConfigurationUtils returns a map of the same types.
            @SuppressWarnings("unchecked")
            final Map<String, Object> clonedMap = (Map<String, Object>) ConfigurationUtils.clone(map);
            copy.map = clonedMap;
            copy.cloneInterpolator(this);
            return copy;
        } catch (final CloneNotSupportedException cex) {
            // cannot happen
            throw new ConfigurationRuntimeException(cex);
        }
    }

@SuppressWarnings("unchecked")
    private static Map<String, Object> convertPropertiesToMap(final Properties props) {
        @SuppressWarnings("rawtypes")
        final Map map = props;
        return map;
    }

@Override
    public String toString() {
        return getClass().getSimpleName() + " [map=" + map + ", trimmingDisabled=" + trimmingDisabled + "]";
    }

@Override
    protected void addPropertyDirect(final String key, final Object value) {
        final Object previousValue = getPropertyInternal(key);

        if (previousValue == null) {
            store.put(key, value);
        } else if (previousValue instanceof List) {
            // safe to case because we have created the lists ourselves
            @SuppressWarnings("unchecked")
            final List<Object> valueList = (List<Object>) previousValue;
            // the value is added to the existing list
            valueList.add(value);
        } else {
            // the previous value is replaced by a list containing the previous value and the new value
            final List<Object> list = new ArrayList<>();
            list.add(previousValue);
            list.add(value);

            store.put(key, list);
        }
    }

@Override
    protected Object getPropertyInternal(final String key) {
        return store.get(key);
    }

@Override
    protected boolean isEmptyInternal() {
        return store.isEmpty();
    }

@Override
    protected boolean containsKeyInternal(final String key) {
        return store.containsKey(key);
    }

@Override
    protected void clearPropertyDirect(final String key) {
        store.remove(key);
    }

@Override
    protected void clearInternal() {
        store.clear();
    }

@Override
    protected int sizeInternal() {
        return store.size();
    }

@Override
    protected Iterator<String> getKeysInternal() {
        return store.keySet().iterator();
    }

@Override
    public Object clone() {
        try {
            final BaseConfiguration copy = (BaseConfiguration) super.clone();
            cloneStore(copy);
            copy.cloneInterpolator(this);

            return copy;
        } catch (final CloneNotSupportedException cex) {
            // should not happen
            throw new ConfigurationRuntimeException(cex);
        }
    }

private void cloneStore(final BaseConfiguration copy) throws CloneNotSupportedException {
        // This is safe because the type of the map is known
        @SuppressWarnings("unchecked")
        final Map<String, Object> clonedStore = (Map<String, Object>) ConfigurationUtils.clone(store);
        copy.store = clonedStore;

        // Handle collections in the map; they have to be cloned, too
        for (final Map.Entry<String, Object> e : store.entrySet()) {
            if (e.getValue() instanceof Collection) {
                // This is safe because the collections were created by ourselves
                @SuppressWarnings("unchecked")
                final Collection<String> strList = (Collection<String>) e.getValue();
                copy.store.put(e.getKey(), new ArrayList<>(strList));
            }
        }
    }

