/**
     * Remove all properties from the configuration.
     */

method_definition:
public void process(final Configuration config) {
        if (config != null) {
            final DefaultExpressionEngine exprEngine = DefaultExpressionEngine.INSTANCE;
            final DefaultConfigurationKey keyEmpty = new DefaultConfigurationKey(exprEngine);
            DefaultConfigurationKey keyLast = keyEmpty;
            final Set<String> keySet = new HashSet<>();

            for (final Iterator<String> it = config.getKeys(); it.hasNext();) {
                final String key = it.next();
                if (keySet.contains(key)) {
                    // this key has already been processed by openElements
                    continue;
                }
                final DefaultConfigurationKey keyAct = new DefaultConfigurationKey(exprEngine, key);
                closeElements(keyLast, keyAct);
                final String elem = openElements(keyLast, keyAct, config, keySet);
                fireValue(elem, config.getProperty(key));
                keyLast = keyAct;
            }

            // close all open
            closeElements(keyLast, keyEmpty);
        }
    }

protected void closeElements(final DefaultConfigurationKey keyLast, final DefaultConfigurationKey keyAct) {
        final DefaultConfigurationKey keyDiff = keyAct.differenceKey(keyLast);
        final Iterator<String> it = reverseIterator(keyDiff);
        if (it.hasNext()) {
            // Skip first because it has already been closed by fireValue()
            it.next();
        }

        while (it.hasNext()) {
            elementEnd(it.next());
        }
    }

protected Iterator<String> reverseIterator(final DefaultConfigurationKey key) {
        final List<String> list = new ArrayList<>();
        for (final DefaultConfigurationKey.KeyIterator it = key.iterator(); it.hasNext();) {
            list.add(it.nextKey());
        }

        Collections.reverse(list);
        return list.iterator();
    }

protected String openElements(final DefaultConfigurationKey keyLast, final DefaultConfigurationKey keyAct, final Configuration config,
        final Set<String> keySet) {
        final DefaultConfigurationKey.KeyIterator it = keyLast.differenceKey(keyAct).iterator();
        final DefaultConfigurationKey k = keyLast.commonKey(keyAct);
        for (it.nextKey(); it.hasNext(); it.nextKey()) {
            k.append(it.currentKey(true));
            elementStart(it.currentKey(true), config.getProperty(k.toString()));
            keySet.add(k.toString());
        }
        return it.currentKey(true);
    }

protected void fireValue(final String name, final Object value) {
        if (value instanceof Collection) {
            final Collection<?> valueCol = (Collection<?>) value;
            for (final Object v : valueCol) {
                fireValue(name, v);
            }
        } else {
            elementStart(name, value);
            elementEnd(name);
        }
    }

@Override
    public boolean compare(final Configuration a, final Configuration b) {
        if (a == null && b == null) {
            return true;
        }
        if (a == null || b == null) {
            return false;
        }

        for (final Iterator<String> keys = a.getKeys(); keys.hasNext();) {
            final String key = keys.next();
            final Object value = a.getProperty(key);
            if (!value.equals(b.getProperty(key))) {
                return false;
            }
        }

        for (final Iterator<String> keys = b.getKeys(); keys.hasNext();) {
            final String key = keys.next();
            final Object value = b.getProperty(key);
            if (!value.equals(a.getProperty(key))) {
                return false;
            }
        }

        return true;
    }

public String getHeader() {
        return header;
    }

public void setHeader(final String header) {
        this.header = header;
    }

@Override
    public void read(final Reader in) throws ConfigurationException {
        final SAXParserFactory factory = SAXParserFactory.newInstance();
        factory.setNamespaceAware(false);
        factory.setValidating(true);

        try {
            final SAXParser parser = factory.newSAXParser();

            final XMLReader xmlReader = parser.getXMLReader();
            xmlReader.setEntityResolver((publicId, systemId) -> new InputSource(getClass().getClassLoader().getResourceAsStream("properties.dtd")));
            xmlReader.setContentHandler(new XMLPropertiesHandler());
            xmlReader.parse(new InputSource(in));
        } catch (final Exception e) {
            throw new ConfigurationException("Unable to parse the configuration file", e);
        }

        // todo: support included properties ?
    }

public void load(final Element element) throws ConfigurationException {
        if (!element.getNodeName().equals("properties")) {
            throw new ConfigurationException(MALFORMED_XML_EXCEPTION);
        }
        final NodeList childNodes = element.getChildNodes();
        for (int i = 0; i < childNodes.getLength(); i++) {
            final Node item = childNodes.item(i);
            if (item instanceof Element) {
                if (item.getNodeName().equals("comment")) {
                    setHeader(item.getTextContent());
                } else if (item.getNodeName().equals("entry")) {
                    final String key = ((Element) item).getAttribute("key");
                    addProperty(key, item.getTextContent());
                } else {
                    throw new ConfigurationException(MALFORMED_XML_EXCEPTION);
                }
            }
        }
    }

@Override
    public void write(final Writer out) throws ConfigurationException {
        final PrintWriter writer = new PrintWriter(out);

        String encoding = locator != null ? locator.getEncoding() : null;
        if (encoding == null) {
            encoding = DEFAULT_ENCODING;
        }
        writer.println("<?xml version=\"1.0\" encoding=\"" + encoding + "\"?>");
        writer.println("<!DOCTYPE properties SYSTEM \"http://java.sun.com/dtd/properties.dtd\">");
        writer.println("<properties>");

        if (getHeader() != null) {
            writer.println("  <comment>" + StringEscapeUtils.escapeXml10(getHeader()) + "</comment>");
        }

        final Iterator<String> keys = getKeys();
        while (keys.hasNext()) {
            final String key = keys.next();
            final Object value = getProperty(key);

            if (value instanceof List) {
                writeProperty(writer, key, (List<?>) value);
            } else {
                writeProperty(writer, key, value);
            }
        }

        writer.println("</properties>");
        writer.flush();
    }

private void writeProperty(final PrintWriter out, final String key, final Object value) {
        // escape the key
        final String k = StringEscapeUtils.escapeXml10(key);

        if (value != null) {
            final String v = escapeValue(value);
            out.println("  <entry key=\"" + k + "\">" + v + "</entry>");
        } else {
            out.println("  <entry key=\"" + k + "\"/>");
        }
    }

private void writeProperty(final PrintWriter out, final String key, final List<?> values) {
        for (final Object value : values) {
            writeProperty(out, key, value);
        }
    }

public void save(final Document document, final Node parent) {
        final Element properties = document.createElement("properties");
        parent.appendChild(properties);
        if (getHeader() != null) {
            final Element comment = document.createElement("comment");
            properties.appendChild(comment);
            comment.setTextContent(StringEscapeUtils.escapeXml10(getHeader()));
        }

        final Iterator<String> keys = getKeys();
        while (keys.hasNext()) {
            final String key = keys.next();
            final Object value = getProperty(key);

            if (value instanceof List) {
                writeProperty(document, properties, key, (List<?>) value);
            } else {
                writeProperty(document, properties, key, value);
            }
        }
    }

