protected synchronized void copyEventListeners(final BasicConfigurationBuilder<?> target) {
        copyEventListeners(target, eventListeners);
    }

protected void copyEventListeners(final BasicConfigurationBuilder<?> target, final EventListenerList listeners) {
        target.eventListeners.addAll(listeners);
    }

protected final <E extends Event> void installEventListener(final EventType<E> eventType, final EventListener<? super E> listener) {
        fetchEventSource().addEventListener(eventType, listener);
        eventListeners.addEventListener(eventType, listener);
    }

protected void fireBuilderEvent(final ConfigurationBuilderEvent event) {
        eventListeners.fire(event);
    }

private void updateParameters(final Map<String, Object> newParams) {
        final Map<String, Object> map = new HashMap<>();
        if (newParams != null) {
            map.putAll(newParams);
        }
        parameters = Collections.unmodifiableMap(map);
    }

private void registerEventListeners(final T obj) {
        final EventSource evSrc = ConfigurationUtils.asEventSource(obj, true);
        for (final EventListenerRegistrationData<?> regData : eventListeners.getRegistrations()) {
            registerListener(evSrc, regData);
        }
    }

private void removeEventListeners(final T obj) {
        final EventSource evSrc = ConfigurationUtils.asEventSource(obj, true);
        for (final EventListenerRegistrationData<?> regData : eventListeners.getRegistrations()) {
            removeListener(evSrc, regData);
        }
    }

private EventSource fetchEventSource() {
        return ConfigurationUtils.asEventSource(result, true);
    }

private void handleEventListenerProviders(final BuilderParameters params) {
        if (params instanceof EventListenerProvider) {
            eventListeners.addAll(((EventListenerProvider) params).getListeners());
        }
    }

private void checkResultInstance(final Object inst) {
        if (!getResultClass().isInstance(inst)) {
            throw new ConfigurationRuntimeException("Incompatible result object: " + inst);
        }
    }

private Map<String, Object> getFilteredParameters() {
        final Map<String, Object> filteredMap = new HashMap<>(getParameters());
        filteredMap.keySet().removeIf(key -> key.startsWith(BuilderParameters.RESERVED_PARAMETER_PREFIX));
        return filteredMap;
    }

private void handleInitializable(final T obj) {
        if (obj instanceof Initializable) {
            ((Initializable) obj).initialize();
        }
    }

private static <E extends Event> void registerListener(final EventSource evSrc, final EventListenerRegistrationData<E> regData) {
        evSrc.addEventListener(regData.getEventType(), regData.getListener());
    }

private static <E extends Event> void removeListener(final EventSource evSrc, final EventListenerRegistrationData<E> regData) {
        evSrc.removeEventListener(regData.getEventType(), regData.getListener());
    }

default T setIncludeListener(final ConfigurationConsumer<ConfigurationException> includeListener) {
        return (T) this;
    }

public <T extends ImmutableConfiguration> T createBuilderConfigurationWrapper(final Class<T> ifcClass, final ConfigurationBuilder<? extends T> builder) {
        return createBuilderConfigurationWrapper(ifcClass, builder, getEventSourceSupport());
    }

public EventSourceSupport getEventSourceSupport() {
        return eventSourceSupport;
    }

public static <T extends ImmutableConfiguration> T createBuilderConfigurationWrapper(final Class<T> ifcClass,
        final ConfigurationBuilder<? extends T> builder, final EventSourceSupport evSrcSupport) {
        if (ifcClass == null) {
            throw new IllegalArgumentException("Interface class must not be null!");
        }
        if (builder == null) {
            throw new IllegalArgumentException("Builder must not be null!");
        }

        return ifcClass.cast(Proxy.newProxyInstance(BuilderConfigurationWrapperFactory.class.getClassLoader(), getSupportedInterfaces(ifcClass, evSrcSupport),
            new BuilderConfigurationWrapperInvocationHandler(builder, evSrcSupport)));
    }

private static Class<?>[] getSupportedInterfaces(final Class<?> ifcClass, final EventSourceSupport evSrcSupport) {
        return EventSourceSupport.NONE == evSrcSupport ? new Class<?>[] {ifcClass} : new Class<?>[] {EventSource.class, ifcClass};
    }

@Override
        public Object invoke(final Object proxy, final Method method, final Object[] args) throws ReflectiveOperationException, ConfigurationException {
            return EventSource.class.equals(method.getDeclaringClass()) ? handleEventSourceInvocation(method, args)
                : handleConfigurationInvocation(method, args);
        }

private Object handleConfigurationInvocation(final Method method, final Object[] args) throws ReflectiveOperationException, ConfigurationException {
            return method.invoke(builder.getConfiguration(), args);
        }

private Object handleEventSourceInvocation(final Method method, final Object... args) throws ReflectiveOperationException {
            return method.invoke(EventSourceSupport.DUMMY == eventSourceSupport ? ConfigurationUtils.asEventSource(this, true) : builder, args);
        }

