private static ReloadingDetectorFactory fetchDetectorFactory(final FileBasedBuilderParametersImpl params) {
        final ReloadingDetectorFactory factory = params.getReloadingDetectorFactory();
        return factory != null ? factory : DEFAULT_DETECTOR_FACTORY;
    }

@Override
    public ReloadingDetector createReloadingDetector(final FileHandler handler, final FileBasedBuilderParametersImpl params) throws ConfigurationException {
        final Long refreshDelay = params.getReloadingRefreshDelay();

        final FileHandlerReloadingDetector fileHandlerReloadingDetector = refreshDelay != null ? new FileHandlerReloadingDetector(handler, refreshDelay)
            : new FileHandlerReloadingDetector(handler);

        fileHandlerReloadingDetector.refresh();

        return fileHandlerReloadingDetector;
    }

public static String getDefaultEncoding(final Class<?> configClass) {
        String enc = DEFAULT_ENCODINGS.get(configClass);
        if (enc != null || configClass == null) {
            return enc;
        }

        final List<Class<?>> superclasses = ClassUtils.getAllSuperclasses(configClass);
        for (final Class<?> cls : superclasses) {
            enc = DEFAULT_ENCODINGS.get(cls);
            if (enc != null) {
                return enc;
            }
        }

        final List<Class<?>> interfaces = ClassUtils.getAllInterfaces(configClass);
        for (final Class<?> cls : interfaces) {
            enc = DEFAULT_ENCODINGS.get(cls);
            if (enc != null) {
                return enc;
            }
        }

        return null;
    }

public static void setDefaultEncoding(final Class<?> configClass, final String encoding) {
        if (configClass == null) {
            throw new IllegalArgumentException("Configuration class must not be null!");
        }

        if (encoding == null) {
            DEFAULT_ENCODINGS.remove(configClass);
        } else {
            DEFAULT_ENCODINGS.put(configClass, encoding);
        }
    }

