@Override
    protected void initResultInstance(final CombinedConfiguration result) throws ConfigurationException {
        super.initResultInstance(result);
        if (reloadingController == null) {
            reloadingController = createReloadingController();
        }
    }

protected ReloadingController createReloadingController() throws ConfigurationException {
        final Collection<ReloadingController> subControllers = new LinkedList<>();
        final ConfigurationBuilder<? extends HierarchicalConfiguration<?>> defBuilder = getDefinitionBuilder();
        obtainReloadingController(subControllers, defBuilder);

        for (final ConfigurationBuilder<? extends Configuration> b : getChildBuilders()) {
            obtainReloadingController(subControllers, b);
        }

        final CombinedReloadingController ctrl = new CombinedReloadingController(subControllers);
        ctrl.resetInitialReloadingState();
        return ctrl;
    }

public static void obtainReloadingController(final Collection<ReloadingController> subControllers, final Object builder) {
        if (builder instanceof ReloadingControllerSupport) {
            subControllers.add(((ReloadingControllerSupport) builder).getReloadingController());
        }
    }

public String getMatchingConfigurationClass() {
        return matchingConfigurationClass;
    }

public String getExtension() {
        return extension;
    }

@Override
    protected String determineConfigurationClass(final ConfigurationDeclaration decl, final Collection<BuilderParameters> params)
        throws ConfigurationException {
        final String currentExt = extractExtension(fetchCurrentFileName(params));
        return getExtension().equalsIgnoreCase(currentExt) ? getMatchingConfigurationClass() : getConfigurationClass();
    }

private static String fetchCurrentFileName(final Collection<BuilderParameters> params) {
        for (final BuilderParameters p : params) {
            if (p instanceof FileBasedBuilderParametersImpl) {
                final FileBasedBuilderParametersImpl fp = (FileBasedBuilderParametersImpl) p;
                return fp.getFileHandler().getFileName();
            }
        }
        return null;
    }

private static String extractExtension(final String fileName) {
        if (fileName == null) {
            return null;
        }

        final int pos = fileName.lastIndexOf(EXT_SEPARATOR);
        return pos < 0 ? null : fileName.substring(pos + 1);
    }

@Override
    protected BasicConfigurationBuilder<? extends Configuration> createBuilder(final ConfigurationDeclaration decl, final Collection<BuilderParameters> params)
        throws Exception {
        final CombinedConfigurationBuilder builder;
        if (decl.isReload()) {
            builder = new ReloadingCombinedConfigurationBuilder();
        } else {
            builder = new CombinedConfigurationBuilder();
        }
        decl.getConfigurationBuilder().initChildEventListeners(builder);
        return builder;
    }

@Override
    protected void initializeParameterObjects(final ConfigurationDeclaration decl, final Collection<BuilderParameters> params) throws Exception {
        // we know that the first object is the combined builder parameters
        // object
        final BasicBuilderParameters basicParams = (BasicBuilderParameters) params.iterator().next();
        setUpBasicParameters(decl.getConfigurationBuilder().getConfigurationUnderConstruction(), basicParams);
        // now properties set explicitly can be overridden
        super.initializeParameterObjects(decl, params);
    }

private static void setUpBasicParameters(final CombinedConfiguration config, final BasicBuilderParameters params) {
        params.setListDelimiterHandler(config.getListDelimiterHandler()).setLogger(config.getLogger())
            .setThrowExceptionOnMissing(config.isThrowExceptionOnMissing()).setConfigurationDecoder(config.getConfigurationDecoder());
    }

