@Override
    public boolean setPosition(final int pos) {
        position = pos;
        return pos >= 1 && pos <= getMaxPosition();
    }

@Override
    public NodePointer getNodePointer() {
        if (getPosition() < 1 && !setPosition(1)) {
            return null;
